/** The Living Manifesto v0.4.3 — universal iPhone Share Sheet intake.
 * Same Cloudflare Worker, D1, converter and credentials. No secrets embedded.
 * Deployment: replace existing deploy.mjs in the GitHub repository root.
 */
import {mkdir,writeFile} from 'node:fs/promises';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {Buffer} from 'node:buffer';
const entries =
[["_headers","","377c696f6ef110d90a5215dcde8f78f91364cdea3840716dfb95655128e2008f"],["_worker.js","","67bcb39be3d8f5584ab112c8a1ae848f2645686db2873b934cbd9a2cf4754355"],["app.js","","fb69a20c7d136db34e136eb24c0b72df421779093d48973b5b9377cd84d50e6e"],["icon-180.png","","9f2ed78e67796b87e56a32f4b974c8b42d7dbc7d2bfe137dc2a8e09d84fc9cb9"],["icon-192.png","","9ae985585f36218e4f3634c480b0d02954d46e62df72f280b2c873b57495815b"],["icon-512.png","","d33a7df296eeff7be392d8b903ac5fff1c6f961de2af3291439cd255fe0af3f0"],["index.html","","618e1ebefc1452fb85064b78288366f41d9067e90ce3a5b3de1f26d17a12b68a"],["manifest.webmanifest","","7bf0277d73f618c7c76e7a27dba501effbe9ada344a5316054a0a3278353dd87"],["service-worker.js","","458888639711dab33a301e0f87d74f9663907646fd9387cc90b97a278d0ddabf"],["styles.css","","5d84b97d20efdb7ae140b41a3e36dadc96e738b0048886f5aedcf3bb373359b6"]];
await mkdir('dist',{recursive:true});
for(const [name,gz,sha] of entries){
 const data=gunzipSync(Buffer.from(gz,'base64'));
 if(createHash('sha256').update(data).digest('hex')!==sha)throw Error('Checksum failed: '+name);
 await writeFile('dist/'+name,data);
 console.log('Prepared '+name+' ('+data.byteLength+' bytes)');
}
console.log('Living Manifesto v0.4.3 ready');
